  private pickNathanTarget(event:PointerEvent){
    if(!this.inputCanvas||!this.nathanControl?.capturing)return;
    this.setMenu(undefined);const r=this.inputCanvas.getBoundingClientRect(),ray=new THREE.Raycaster();
    ray.setFromCamera(new THREE.Vector2((event.clientX-r.left)/r.width*2-1,1-(event.clientY-r.top)/r.height*2),this.camera);
    const hits=ray.intersectObjects([...this.objects.values()],true);
    for(const hit of hits){
      let node:THREE.Object3D|null=hit.object;while(node&&!node.userData.entityId)node=node.parent;
      const entity=this.history.current.entities.find(e=>e.id===node?.userData.entityId);if(!entity)continue;
      if(entity.id===this.nathanControl.id)continue;
      if(entity.preset===NATHAN_PRESET){this.selection=new Set([entity.id]);this.refreshSelection();this.openPerson(entity);return;}
      const access=nathanAccessKind(hit.object,entity);
      if(access){this.nathanControl.climb(entity.id,access);return;}
      if(entity.kind!=='ground'){this.notify(this.say('Boş zemini veya merdivenin basamaklarını seçin. Panelden de merdiven seçebilirsiniz.','Choose clear ground or a stair tread. You can also choose access in the panel.'));return;}
      break;
    }
    const point=ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),0),new THREE.Vector3());
    if(point)this.nathanControl.walkTo(point.toArray() as [number,number,number]);
  }
