  private updateGroundStatus(){const el=this.root.querySelector('#wsMapStatus');if(!el)return;el.textContent=this.groundMode()==='ortho'?(this.staticGround?.failed?this.say('Zemin yüklenemedi; yenilemeyi deneyin.','Ground could not load; try reloading.'):this.staticGround?.ready===2?this.say('Ortak sabit zemin · 3 × 5,1 km','Shared static ground · 3 × 5.1 km'):this.say('Sabit zemin yükleniyor…','Loading static ground…')):this.groundMode()==='photo'?this.say('Referans fotoğraf · yaklaşık hizalama','Reference photo · approximate alignment'):this.say('Zemin planı','Ground plan');}
  private async save(){if(!this.cloud.canEdit){this.unlockDesign();return false;}if(this.saving)return false;this.nathanControl?.pause();this.personnel?.pause();this.driving?.pause();this.saving=true;this.updateSaveState();const snapshot=structuredClone(this.history.current);try{const ok=await this.cloud.save(snapshot);if(ok){this.session.commit(snapshot,json=>localStorage.setItem(STORE,json));this.storageWarning=false;this.renderList();}return ok;}catch{this.storageWarning=true;this.notify(this.say('Kayıt yapılamadı. JSON dışarı aktar ile yedekleyin.','Save failed. Export JSON for backup.'));return false;}finally{this.saving=false;this.updateSaveState();}}
