  async requestLeave(discard=false):Promise<boolean>{
    this.closeNathan();this.personnel?.close();this.driving?.pause();
    if(!this.cloud?.canEdit){this.driving?.close();if(this.session){this.history=new SceneHistory(this.session.discard());this.selection.clear();this.changed();}if(this.editing)this.setEditing(false);return true;}
    if(!this.session||!this.session.dirty(this.history.current)){if(this.editing)this.setEditing(false);return true;}
    if(this.exitDialog)return this.exitDialog;
    this.exitDialog=new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='ws-dialog';dialog.innerHTML=`<h2>${this.say('Değişiklikler kaydedilmedi','Changes are not saved')}</h2><p>${this.say('Kaydetmeden çıkarsanız son kayıtlı sahneniz geri gelir.','Discarding restores your last saved scene.')}</p><div><button data-result="save">${this.say('Kaydet ve çık','Save & exit')}</button><button data-result="discard">${this.say('Kaydetmeden çık','Discard & exit')}</button><button data-result="cancel">${this.say('Düzenlemeye devam','Continue editing')}</button></div>`;this.root.appendChild(dialog);const finish=async(value:string)=>{if(value==='save'&&!await this.save())return;if(value==='discard'){this.driving?.close();this.history=new SceneHistory(this.session.discard());this.selection.clear();this.changed();}if(value!=='cancel')this.setEditing(false);dialog.close();dialog.remove();this.exitDialog=undefined;resolve(value!=='cancel');};dialog.querySelectorAll<HTMLButtonElement>('button').forEach(b=>b.onclick=()=>finish(b.dataset.result!));dialog.oncancel=e=>{e.preventDefault();finish('cancel');};dialog.showModal();dialog.querySelector<HTMLButtonElement>(`[data-result="${discard?'discard':'save'}"]`)!.focus();});return this.exitDialog;
  }
  private viewCenter():[number,number]{if(this.freeMode){const dir=this.camera.getWorldDirection(new THREE.Vector3());const p=new THREE.Ray(this.camera.position,dir).intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),0),new THREE.Vector3())||this.camera.position.clone().addScaledVector(dir,40);return [p.x,p.z];}return this.orbit?[this.orbit.target.x,this.orbit.target.z]:[0,0];}
