  private tintGround(){this.groundScene.traverse(n=>{if(n instanceof THREE.Mesh&&n.material instanceof THREE.MeshBasicMaterial&&n.renderOrder<1100){const m=n.material;const base=m.userData.dayColor??(m.userData.dayColor=m.color.clone());m.color.copy(base);if(this.night)m.color.multiply(new THREE.Color(.18,.24,.36));}});}
